// OTIZ-OBJECT-LEDGER-HISTORY-001: public existing snapshot HTTP/browser seam.
function olhStart(string $root,array $environment,string $log):array
{
    $listener=stream_socket_server('tcp://127.0.0.1:0',$code,$message);
    if(!is_resource($listener))throw new TestFailure('SETUP_FAILURE: port '.$message);
    preg_match('/:(\d+)$/D',(string)stream_socket_get_name($listener,false),$match);$port=(int)$match[1];fclose($listener);
    $env=getenv();foreach(array_keys($env)as$key)if(str_starts_with((string)$key,'FMONITOR_'))unset($env[$key]);
    $env=array_replace($env,$environment,['FMONITOR_TRUSTED_REQUEST_HOST'=>'127.0.0.1:'.$port]);
    $pipes=[];$process=proc_open([PHP_BINARY,'-d','display_errors=0','-S','127.0.0.1:'.$port,$root.'/public/yii.php'],[0=>['file','/dev/null','r'],1=>['file',$log,'a'],2=>['file',$log,'a']],$pipes,$root,$env);
    if(!is_resource($process))throw new TestFailure('SETUP_FAILURE: Yii server');
    $deadline=microtime(true)+5;do{$socket=@fsockopen('127.0.0.1',$port,$code,$message,.1);if(is_resource($socket)){fclose($socket);return['process'=>$process,'port'=>$port];}usleep(20000);}while(microtime(true)<$deadline);
    throw new TestFailure('SETUP_FAILURE: Yii listener '.(string)@file_get_contents($log));
}
function olhStop(?array&$server):void{if($server===null)return;proc_terminate($server['process']);proc_close($server['process']);$server=null;}
function olhRequest(array$server,string$method,string$path,array&$cookies):array
{
    $headers=['Host: 127.0.0.1:'.$server['port'],'Connection: close'];if($cookies)$headers[]='Cookie: '.implode('; ',array_map(static fn($key,$value)=>"$key=$value",array_keys($cookies),$cookies));
    $context=stream_context_create(['http'=>['ignore_errors'=>true,'follow_location'=>0,'method'=>$method,'header'=>implode("\r\n",$headers)]]);
    $body=file_get_contents('http://127.0.0.1:'.$server['port'].$path,false,$context);$raw=$http_response_header??[];$responseHeaders=[];
    foreach(array_slice($raw,1)as$line){$at=strpos($line,':');if($at!==false)$responseHeaders[strtolower(substr($line,0,$at))][]=trim(substr($line,$at+1));}
    foreach($responseHeaders['set-cookie']??[]as$cookie)if(preg_match('/^([^=;]+)=([^;]*)/',$cookie,$match))$cookies[$match[1]]=$match[2];
    preg_match('#^HTTP/\S+ (\d+)#',$raw[0]??'',$match);return['status'=>(int)($match[1]??0),'headers'=>$responseHeaders,'body'=>(string)$body];
}
function olhPost(array$server,string$path,array$form,array&$cookies):array
{
    $body=http_build_query($form);$headers=['Host: 127.0.0.1:'.$server['port'],'Connection: close','Content-Type: application/x-www-form-urlencoded'];if($cookies)$headers[]='Cookie: '.implode('; ',array_map(static fn($key,$value)=>"$key=$value",array_keys($cookies),$cookies));
    $context=stream_context_create(['http'=>['ignore_errors'=>true,'follow_location'=>0,'method'=>'POST','header'=>implode("\r\n",$headers),'content'=>$body]]);
    $content=file_get_contents('http://127.0.0.1:'.$server['port'].$path,false,$context);$raw=$http_response_header??[];$responseHeaders=[];
    foreach(array_slice($raw,1)as$line){$at=strpos($line,':');if($at!==false)$responseHeaders[strtolower(substr($line,0,$at))][]=trim(substr($line,$at+1));}
    foreach($responseHeaders['set-cookie']??[]as$cookie)if(preg_match('/^([^=;]+)=([^;]*)/',$cookie,$match))$cookies[$match[1]]=$match[2];preg_match('#^HTTP/\S+ (\d+)#',$raw[0]??'',$match);
    return['status'=>(int)($match[1]??0),'headers'=>$responseHeaders,'body'=>(string)$content];
}
function olhCsrf(string$html):string{if(!preg_match('/name="_csrf" value="([^"]+)"/',$html,$match))throw new TestFailure('SETUP_FAILURE: csrf');return html_entity_decode($match[1],ENT_QUOTES|ENT_HTML5,'UTF-8');}
function olhClosureIds(string$html):array{preg_match_all('/data-otiz-object-ledger-row[^>]*data-closure-id="(\d+)"/',$html,$matches);return array_map('intval',$matches[1]);}
function olhInventory(mysqli$db,string$prefix):array
{
    $tables=['fm2_pilot_otiz_snapshots','fm2_pilot_otiz_snapshot_objects','fm2_pilot_otiz_payment_closures','fm2_pilot_otiz_events','fm2_otiz_settlement_operations','fm2_jobs','fm2_outbox_intents'];$result=[];
    foreach($tables as$table)$result[$table]=[(int)$db->query("SELECT COUNT(*) FROM `{$prefix}{$table}`")->fetch_column(),hash('sha256',json_encode($db->query("SELECT * FROM `{$prefix}{$table}` ORDER BY 1")->fetch_all(MYSQLI_ASSOC),JSON_THROW_ON_ERROR))];return$result;
}
